// Verify HMAC-SHA256 of RAW body (ADR-0003).
// Requires Webhook option rawBody=true. Secret: env N8N_WEBHOOK_SECRET (same as Management).
const crypto = require('crypto');

const secret = (typeof process !== 'undefined' && process.env && process.env.N8N_WEBHOOK_SECRET) || '';
if (!secret || !String(secret).trim()) {
  throw new Error('N8N_WEBHOOK_SECRET ausente — fail closed');
}

const item = $input.first();
const headers = item.json.headers || {};
const provided = String(
  headers['x-avs-signature'] || headers['X-AVS-Signature'] || ''
).trim();
if (!provided) {
  throw new Error('X-AVS-Signature ausente');
}

let rawBuf;
if (item.binary && item.binary.data) {
  rawBuf = await this.helpers.getBinaryDataBuffer(0, 'data');
} else if (typeof item.json.body === 'string') {
  rawBuf = Buffer.from(item.json.body, 'utf8');
} else if (item.json.body && typeof item.json.body === 'object') {
  // Fallback frágil — preferir rawBody; só para smoke local
  rawBuf = Buffer.from(JSON.stringify(item.json.body), 'utf8');
} else {
  throw new Error('Raw body indisponível — habilite rawBody no Webhook');
}

const expected = crypto.createHmac('sha256', String(secret).trim()).update(rawBuf).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(expected, 'utf8'), Buffer.from(provided, 'utf8'))) {
  throw new Error('Assinatura HMAC inválida');
}

const envelope = JSON.parse(rawBuf.toString('utf8'));
return [{ json: envelope }];

// dry_run: sem VHSYS/TiFlux — callback ok imediato
const e = $input.first().json;
const run = (e.payload && e.payload.billing_run) || {};
return [{
  json: {
    event: e.event,
    resource_type: e.resource_type,
    resource_id: e.resource_id,
    status: 'ok',
    outbox_id: e.outbox_id,
    external: {
      tiflux_ticket_number: run.tiflux_ticket_number || null,
      vhsys_nf_id: run.vhsys_nf_id || null,
      vhsys_cr_id: run.vhsys_cr_id || null
    },
    error_message: null,
    dry_run: true,
    _callback_url: e.callback_url
  }
}];

// PLACEHOLDER billing.approved live
// Ops: VHSYS POST /notas-servico + POST /contas-receber (+ boleto) +
// TiFlux POST /tickets + 3x files (report, nf, boleto).
// Ver docs/hub/n8n/avs-hub-billing.md §6.
const e = $input.first().json;
const run = (e.payload && e.payload.billing_run) || {};
const hasRet = !!(e.payload && e.payload.has_retencao) || !!run.has_retencao;
if (hasRet) {
  return [{
    json: {
      event: e.event,
      resource_type: e.resource_type,
      resource_id: e.resource_id,
      status: 'error',
      outbox_id: e.outbox_id,
      external: null,
      error_message: 'billing.approved with has_retencao=true — use billing.nf_prefeitura after prefeitura',
      dry_run: false,
      _callback_url: e.callback_url
    }
  }];
}
return [{
  json: {
    event: e.event,
    resource_type: e.resource_type,
    resource_id: e.resource_id,
    status: 'error',
    outbox_id: e.outbox_id,
    external: null,
    error_message: 'billing.approved live nodes not wired — configure VHSYS NF/CR + TiFlux ticket after smoke',
    dry_run: false,
    _callback_url: e.callback_url
  }
}];

// PLACEHOLDER billing.nf_prefeitura live
// Ops: VHSYS POST /contas-receber com net_total (SEM NF VHSYS) +
// TiFlux ticket + anexos (report + NF prefeitura + boleto).
// Ver docs/hub/n8n/avs-hub-billing.md §6.
const e = $input.first().json;
return [{
  json: {
    event: e.event,
    resource_type: e.resource_type,
    resource_id: e.resource_id,
    status: 'error',
    outbox_id: e.outbox_id,
    external: null,
    error_message: 'billing.nf_prefeitura live nodes not wired — configure VHSYS CR líquido + TiFlux after smoke',
    dry_run: false,
    _callback_url: e.callback_url
  }
}];

const e = $input.first().json;
return [{
  json: {
    event: e.event,
    resource_type: e.resource_type,
    resource_id: e.resource_id,
    status: 'error',
    outbox_id: e.outbox_id,
    external: null,
    error_message: 'unknown event: ' + String(e.event),
    dry_run: !!e.dry_run,
    _callback_url: e.callback_url
  }
}];

// Assina CallbackPayload e POST em callback_url (ADR-0003)
const crypto = require('crypto');
const secret = (typeof process !== 'undefined' && process.env && process.env.N8N_WEBHOOK_SECRET) || '';
if (!secret || !String(secret).trim()) {
  throw new Error('N8N_WEBHOOK_SECRET ausente — fail closed');
}

const src = $input.first().json;
const callbackUrl = src._callback_url;
if (!callbackUrl || typeof callbackUrl !== 'string') {
  throw new Error('callback_url ausente');
}

const bodyObj = {
  event: src.event,
  resource_type: src.resource_type,
  resource_id: src.resource_id,
  status: src.status,
  outbox_id: src.outbox_id,
  external: src.external ?? null,
  error_message: src.error_message ?? null,
  dry_run: src.dry_run ?? null
};

const raw = JSON.stringify(bodyObj);
const signature = crypto.createHmac('sha256', String(secret).trim()).update(Buffer.from(raw, 'utf8')).digest('hex');

return [{
  json: {
    callback_url: callbackUrl,
    body: bodyObj,
    raw_body: raw,
    signature
  }
}];
